import os
import hashlib
import json
from pathlib import Path

def task_func(directory: str) -> str:
    base_dir = Path(directory).expanduser().resolve()
    if not base_dir.exists():
        raise FileNotFoundError(f"Directory does not exist: {directory}")
    if not base_dir.is_dir():
        raise NotADirectoryError(f"Not a directory: {directory}")

    output_path = base_dir / "hashes.json"
    hashes = {}

    for path in sorted(base_dir.rglob("*")):
        if not path.is_file():
            continue
        # Avoid self-reference if hashes.json already exists
        if path.resolve() == output_path.resolve():
            continue

        rel_path = path.relative_to(base_dir).as_posix()
        sha256 = hashlib.sha256()

        with path.open("rb") as f:
            for chunk in iter(lambda: f.read(8192), b""):
                sha256.update(chunk)

        hashes[rel_path] = sha256.hexdigest()

    with output_path.open("w", encoding="utf-8") as f:
        json.dump(hashes, f, ensure_ascii=False, indent=2, sort_keys=True)

    return str(output_path.resolve())
